import { generateHumanCode } from '../common/crypto/human-code.util';

/**
 * Team invite codes are generated by the server (owner decision,
 * 2026-11-08 — ADR-0009's 2026-11-08 amendment, superseding Decision 3).
 *
 * Until then the team's creator typed the code, so real codes were things
 * like `IBK2014` or a club name plus a birth year — guessable by anyone
 * who knows the club — and `GET /teams/invite/:code` confirmed a guess by
 * answering with the team's name. A code is the only thing between a
 * stranger and a join request on a children's team, so it has to be
 * something nobody can guess.
 *
 * Reuses `generateHumanCode` deliberately rather than a new generator: it
 * is already the code this app has children read and type (PT invites,
 * erasure and contact-change codes) — 8 characters from a 32-character
 * alphabet with 0/O and 1/I removed, 40 bits, which at the invite
 * lookup's 10/min/IP throttle is not enumerable.
 */
export function generateTeamInviteCode(): string {
  // ttl 0: an invite code has no expiry of its own; it lives until the
  // captain rotates it.
  return generateHumanCode(0).code;
}

/**
 * Lookups compare against a normalised form, so a child who types the
 * code in lower case, or with a stray space, still finds the team.
 * Generated codes are upper case by construction, and the 2026-11-08
 * migration replaced every code that predates generation, so no stored
 * code differs from its normalised form.
 */
export function normalizeInviteCode(raw: string): string {
  return raw.trim().toUpperCase();
}
